{
  "a_sentences": [
    {
      "a_text": "La personne assurée supporte le fardeau de la preuve de la survenance du cas d'assurance et de l'étendue de la prestation (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "L'art. 39 LCA ne modifie pas la répartition du fardeau de la preuve selon l'art. 8 CC, mais impose un échange d'informations coopératif après l'annonce du sinistre (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le but de l'assurance est de répartir les dommages effectifs sur un grand nombre de personnes exposées de manière similaire, et non de couvrir des dommages hypothétiques (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "En assurance d'une indemnité journalière, le besoin d'une instruction rapide est plus élevé qu'en assurance-invalidité, car ces prestations remplacent le revenu courant et sont influencées par l'état de santé actuel (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Si l'assureur refuse une prestation sans aucune instruction ou sur la base d'une instruction manifestement insuffisante, il contourne le processus de règlement prévu par la loi et contraint l'assuré à prouver son droit dans un procès où il supporte le fardeau de la preuve (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "C'est ce comportement de l'assureur qui est critiqué dans l'arrêt cantonal (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme l'arrêt cantonal et rejette le recours de l'assureur (P8).",
      "b_propositions": ["P8"]
    },
    {
      "a_text": "La juridiction cantonale a retenu qu'il restait à examiner si l'assureur avait échoué à apporter la preuve du contraire (P1).",
      "b_propositions": ["P1"]
    }
  ]
}
